import React from "react";
import { Link, useNavigate } from "react-router-dom";
import "../css/Navbar.css";

const Navbar = ({ user, setUser }) => {
  const navigate = useNavigate();

  const handleLogout = () => {
    setUser(null);
    navigate("/");
  };

  return (
    <nav className="navbar">
      <h3>İzin Yönetim Sistemi</h3>
      <ul className="nav-links">
        {user && user.role === "MANAGER" && (
          <>
            <li><Link to="/manager-dashboard">Yönetici Paneli</Link></li>
            <li><Link to="/add-employee">Çalışan Ekle</Link></li>
          </>
        )}
        {user && user.role === "EMPLOYEE" && (
          <>
            <li><Link to="/employee-dashboard">Çalışan Paneli</Link></li>
            <li><Link to="/new-leave-request">İzin Talep Et</Link></li>
          </>
        )}
        {user && (
          <>
            <li><Link to="/user-profile">Profilim</Link></li>
            <li><button className="logout-button" onClick={handleLogout}>Çıkış Yap</button></li>
          </>
        )}
      </ul>
    </nav>
  );
};

export default Navbar;
